const slides=[...document.querySelectorAll('.slide')],dots=document.getElementById('dots'),canvas=document.getElementById('visual'),ctx=canvas.getContext('2d');let current=0,playing=false,timer=null,w=innerWidth,h=innerHeight;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
slides.forEach((s,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.setAttribute('aria-label',`Slide ${i+1}`);b.onclick=()=>go(i);dots.append(b)});
function go(n){if(window.NeuroIntro?.active){window.NeuroIntro.skip();return;}current=Math.max(0,Math.min(5,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i!==current);s.inert=i!==current});[...dots.children].forEach((b,i)=>{b.classList.toggle('selected',i===current);b.setAttribute('aria-current',i===current?'step':'false')});document.getElementById('count').textContent=`0${current+1} / 06`;document.getElementById('progress').style.width=`${(current+1)/6*100}%`;document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===5;history.replaceState(null,'',`#${current+1}`);window.NeuroIntro?.setSlide(current);if(current>=2&&current<=4)window.NeuroIntro?.play();}
document.getElementById('next').onclick=()=>go(current+1);document.getElementById('prev').onclick=()=>go(current-1);document.getElementById('restart').onclick=()=>go(0);document.getElementById('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>{})};document.getElementById('auto').onclick=()=>{playing=!playing;document.getElementById('auto').textContent=playing?'Ⅱ PAUSE':'▷ AUTO';clearInterval(timer);if(playing)timer=setInterval(()=>go((current+1)%6),10000)};
addEventListener('keydown',e=>{if(e.target.closest('button,a'))return;if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key==='Home')go(0);if(e.key==='End')go(5)});let touchX=0;addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>60)go(current+(dx<0?1:-1))},{passive:true});
const steps=document.getElementById('steps');for(let i=0;i<16;i++){const el=document.createElement('div');el.className='step'+(i%4===0?' hit':'');steps.append(el)}
