function draw(ms){const t=reduced?0:ms/1000;ctx.clearRect(0,0,w,h);if(current===1||current===4||current===5){const cx=w>.8*h?w*.75:w*.5,cy=current===1?h*.53:h*.65;for(let j=0;j<20;j++){ctx.beginPath();ctx.strokeStyle=`rgba(199,255,0,${.07+(j%5)*.025})`;ctx.lineWidth=j%7===0?1.4:.65;for(let k=0;k<=220;k++){const x=w*.44+k/220*w*.56;const y=cy+Math.sin(k*.043+t*.7+j*.12)*Math.sin(k/220*Math.PI)*(45+j*3)+j*2;if(k===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke()}}if(current===3){const step=Math.floor(t*8)%16;[...steps.children].forEach((e,i)=>e.classList.toggle('on',i===step))}if(!reduced)requestAnimationFrame(draw)}go((parseInt(location.hash.slice(1))||1)-1);requestAnimationFrame(draw);if(reduced){const originalGo=go;addEventListener('hashchange',()=>draw(0));new MutationObserver(()=>draw(0)).observe(document.getElementById('count'),{childList:true})}
